window.KB=[{"id":"01-1","topic":"nature","ctx":"Accepted extent and boundary of the Dooars; districts","text":"Sankosh divides it into Eastern and Western Dooars; Wikipedia gives the combined area as 880 km2, with elevation 90 to 1,750 m and \"18 passes\" between Bhutan hills and Indian plains","kind":"conflict","src":[{"l":"Wikipedia: Dooars","u":"https://en.wikipedia.org/wiki/Dooars"},{"l":"CONFLICT/likely error: 880 km2 is implausible fo","u":"https://ir.nbu.ac.in/bitstreams/7c0564ad-bca8-4590-aa36-446035813382/download"}]},{"id":"01-2","topic":"nature","ctx":"Accepted extent and boundary of the Dooars; districts","text":"Travel sources describe the Bengal Dooars as roughly 130 km (Teesta to Sankosh) x 40 km (rough rectangle, not a measured area)","kind":"operator","src":[{"l":"East Himalaya","u":"https://www.east-himalaya.com/dooars"}]},{"id":"01-3","topic":"nature","ctx":"Accepted extent and boundary of the Dooars; districts","text":"Assam portion (historical divisions): Eastern Dooars lie between Sankosh and Manas; Kamrup Dooars between Manas and Bornadi; Darrang Dooars between Bornadi and Dhansiri. Assam districts today: Kokrajhar, Chirang, Bongaigaon, Goalpara, Baksa, Udalguri etc. (BTR region)","kind":"report","src":[{"l":"Wikipedia: Dooars","u":"https://en.wikipedia.org/wiki/Dooars"}]},{"id":"01-4","topic":"nature","ctx":"Accepted extent and boundary of the Dooars; districts","text":"West Bengal districts per Wikipedia: Kalimpong (foothills), Jalpaiguri, Alipurduar, upper part of Cooch Behar","kind":"report","src":[{"l":"Wikipedia: Dooars","u":"https://en.wikipedia.org/wiki/Dooars"}]},{"id":"01-5","topic":"nature","ctx":"Accepted extent and boundary of the Dooars; districts","text":"Gorumara (Jalpaiguri, Malbazar subdivision) is about 17 km from Mainaguri and about 80 km from Bagdogra airport","kind":"report","src":[{"l":"Wikipedia: Gorumara","u":"https://en.wikipedia.org/wiki/Gorumara_National_Park"}]},{"id":"01-6","topic":"nature","ctx":"Accepted extent and boundary of the Dooars; districts","text":"Jaldapara and Chilapata are in Alipurduar district (nearest towns Madarihat, Birpara, Hasimara); Neora Valley NP is in Kalimpong district","kind":"report","src":[{"l":"Jaldapara","u":"https://en.wikipedia.org/wiki/Jaldapara_National_Park"},{"l":"Chilapata","u":"https://en.wikipedia.org/wiki/Chilapata_Forests"}]},{"id":"01-7","topic":"nature","ctx":"Accepted extent and boundary of the Dooars; districts","text":"Ecoregion: Terai-Duar savanna and grasslands","kind":"report","src":[{"l":"Wikipedia: Dooars","u":"https://en.wikipedia.org/wiki/Dooars"}]},{"id":"01-8","topic":"nature","ctx":"Rivers, climate, rainfall, seasons","text":"Named rivers: Teesta, Torsha (Torsa), Jaldhaka, Sankosh, Raidak, Murti, Manas","kind":"report","src":[{"l":"Wikipedia: Dooars","u":"https://en.wikipedia.org/wiki/Dooars"}]},{"id":"01-9","topic":"nature","ctx":"Rivers, climate, rainfall, seasons","text":"Jalpaiguri rivers: Dharla, Jaldhaka, Karala, Teesta, Torsha","kind":"report","src":[{"l":"Wikipedia: Jalpaiguri district","u":"https://en.wikipedia.org/wiki/Jalpaiguri_district"}]},{"id":"01-10","topic":"nature","ctx":"Rivers, climate, rainfall, seasons","text":"Gorumara is on Jaldhaka, Murti and Raidak floodplains; Chapramari fed by Teesta, Neora, Jaldhaka, Murti; Jaldapara on Torsa; Buxa: Raidak and Jayanti rivers, Narathali lake","kind":"report","src":[{"l":"Gorumara","u":"https://en.wikipedia.org/wiki/Gorumara_National_Park"},{"l":"Chapramari","u":"https://en.wikipedia.org/wiki/Chapramari_Wildlife_Sanctuary"}]},{"id":"01-11","topic":"nature","ctx":"Rivers, climate, rainfall, seasons","text":"Jalpaiguri district rainfall: annual average 3,160 mm; wettest July (809.3 mm); driest December (0.2 mm)","kind":"report","src":[{"l":"Wikipedia: Jalpaiguri district","u":"https://en.wikipedia.org/wiki/Jalpaiguri_district"}]},{"id":"01-12","topic":"nature","ctx":"Rivers, climate, rainfall, seasons","text":"Siliguri/Bagdogra normals 1991-2020 (nearby proxy): annual 3,011 mm over about 132 rainy days; July 843 mm, June 628 mm, August 589 mm; Nov and Dec about 10-11 mm; mean max 27.7 °C, mean min 18.7 °C; record high 41.9 °C, record low 1.9 °C; humidity 75% (about 90% in July)","kind":"report","src":[{"l":"Wikipedia: Dooars","u":"https://en.wikipedia.org/wiki/Dooars"}]},{"id":"01-13","topic":"nature","ctx":"Rivers, climate, rainfall, seasons","text":"Elevation range 90 to 1,750 m (Wikipedia)","kind":"report","src":[{"l":"Wikipedia: Dooars","u":"https://en.wikipedia.org/wiki/Dooars"}]},{"id":"01-14","topic":"nature","ctx":"Gorumara NP (Jalpaiguri)","text":"Closed 16 June-15 September (monsoon); watchtowers: Jatraprasad, Rhino Observation Point, Chandrachur, Chukchuki, Medla","kind":"report","src":[{"l":"Wikipedia: Gorumara","u":"https://en.wikipedia.org/wiki/Gorumara_National_Park"}]},{"id":"01-15","topic":"nature","ctx":"Gorumara NP (Jalpaiguri)","text":"Reopened 16 Sept 2024 (reported Monday after 3 months); about 200 tourists on the first day; entrances Ramsai, Murti, Gorumara main; 3 elephants for safari in 2024 (2 in 2023)","kind":"report","src":[{"l":"Millennium Post, 17 Sep 2024","u":"https://www.millenniumpost.in/bengal/gorumara-national-park-reopens-after-3-months-with-enhanced-safaris-and-new-attractions-579849"}]},{"id":"01-16","topic":"nature","ctx":"Gorumara NP (Jalpaiguri)","text":"Jeep safari tickets issued at Lataguri Nature Interpretation Centre counter (closed in closure period); online via WBFDC (July 2025 blog; not an official page)","kind":"operator","src":[{"l":"Resort Trimurti guide","u":"https://www.resorttrimurti.com/blog/dooars-jungle-safari-price-booking-best-time-complete-travel-guide"}]},{"id":"01-17","topic":"nature","ctx":"Jaldapara NP (Alipurduar)","text":"Online safari booking opened 14 Oct 2026: 912 safari seats/day across five routes (Salkumar, Madarihat, Lankapara, Chilapata, Kodalbasti); 48 elephant-ride seats bookable online; bookings up to one month in advance (full article paywalled)","kind":"report","src":[{"l":"UNI, 14 Oct 2026","u":"https://www.uniindia.com/east-india/tourism-wb-jaldapara-durga-puja/214066"}]},{"id":"01-18","topic":"nature","ctx":"Jaldapara NP (Alipurduar)","text":"Closure reported as 15 June-15 September by a travel site; no official notice found","kind":"unverified","src":[{"l":"GoTirupati summary via search","u":"https://gotirupati.com/?p=41289"}]},{"id":"01-19","topic":"nature","ctx":"Buxa Tiger Reserve (Alipurduar)","text":"Total 760.87 km2: core/critical tiger habitat 390.58, buffer 370.29 (NTCA brief, 2019 document, figures per search snippet)","kind":"official","src":[{"l":"NTCA Buxa brief","u":"https://ntca.gov.in/assets/uploads/briefnote/buxa.pdf"}]},{"id":"01-20","topic":"nature","ctx":"Buxa Tiger Reserve (Alipurduar)","text":"Tiger reserve 1983 (India's 15th); sanctuary 1986 (314.52 km2) +54.47 km2 in 1991; national park 117.10 km2 notified 5 Dec 1997; elevation 60 to 1,750 m; 284+ bird, 73 mammal, 65 fish, 41 reptile species; elephant corridor to Bhutan (Phibsoo WLS adjoining)","kind":"report","src":[{"l":"Wikipedia: Buxa","u":"https://en.wikipedia.org/wiki/Buxa_Tiger_Reserve"}]},{"id":"01-21","topic":"nature","ctx":"Chapramari WLS (Jalpaiguri)","text":"960 hectares (about 9.6 km2); reserve forest 1895; sanctuary 1998; known for elephants and gaur; Teesta/Neora/Jaldhaka/Murti rivers; 2013 train collision killed 5 adults and 2 calves from a herd of 40-50","kind":"report","src":[{"l":"Wikipedia: Chapramari","u":"https://en.wikipedia.org/wiki/Chapramari_Wildlife_Sanctuary"}]},{"id":"01-22","topic":"nature","ctx":"Chilapata Forests (Alipurduar)","text":"Corridor linking Jaldapara and Buxa; about 40 km from Alipurduar town, near Hasimara; Naranarayan Garh ruins; leopards common; area not given","kind":"report","src":[{"l":"Wikipedia: Chilapata","u":"https://en.wikipedia.org/wiki/Chilapata_Forests"}]},{"id":"01-23","topic":"nature","ctx":"Neora Valley NP (Kalimpong)","text":"88 km2 per Wikipedia; established 1986; elevation 183-3,200 m; red panda, clouded leopard, golden cat; tiger photographed 2017 (first in 40 years) and Dec 2023","kind":"conflict","src":[{"l":"Wikipedia: Neora Valley","u":"https://en.wikipedia.org/wiki/Neora_Valley_National_Park"},{"l":"Millennium Post, Nov 2025","u":"https://www.millenniumpost.in/bengal/intensive-tiger-census-to-begin-in-january-2026-637004"}]},{"id":"01-24","topic":"nature","ctx":"Fees (all third-party, unverified)","text":"Jeep safari per jeep: INR 2,500-4,000 (Gorumara/Chapramari), INR 3,500-4,500 (Jaldapara); elephant safari about INR 1,000-1,500 per person (2026 travel guide)","kind":"unverified","src":[{"l":"Resort Trimurti","u":"https://www.resorttrimurti.com/blog/dooars-jungle-safari-price-booking-best-time-complete-travel-guide"}]},{"id":"01-25","topic":"nature","ctx":"Fees (all third-party, unverified)","text":"Another site lists elephant safari Rs 140 and entry Rs 25 per adult: likely outdated","kind":"old","src":[]},{"id":"01-26","topic":"nature","ctx":"Wildlife counts from censuses","text":"Elephants North Bengal about 676 in the latest survey (Oct 2025 report; national forest elephants 22,446 vs 29,964 in 2017)","kind":"conflict","src":[{"l":"Millennium Post, 18 Oct 2025","u":"https://www.millenniumpost.in/nation/north-bengal-sees-rise-in-elephant-population-amid-national-decline-631744"},{"l":"CONFLICT: Down To Earth says about 630 in north ","u":"https://www.downtoearth.org.in/agriculture/conflict-in-the-backyard-community-patrols-cut-crop-damage-in-north-bengal-but-south-bengals-farmers-remain-exposed"}]},{"id":"01-27","topic":"nature","ctx":"Wildlife counts from censuses","text":"Tigers: Buxa one resident in 2005 ; recent camera evidence 2021, 2023 (above)","kind":"old","src":[]},{"id":"01-28","topic":"nature","ctx":"Wildlife counts from censuses","text":"Gorumara species totals: 194 birds, 50 mammals; Buxa 284+ birds, 73 mammals (above)","kind":"report","src":[]},{"id":"01-29","topic":"nature","ctx":"Wildlife counts from censuses","text":"Gaur: present in Gorumara, Jaldapara and Chapramari; no official count found.","kind":"report","src":[]},{"id":"01-30","topic":"nature","ctx":"Elephant corridors and human-wildlife conflict relevant to visitors","text":"Train deaths in north Bengal: over 50 elephants 2004-2013; about 30 more 2013-2023, mainly on Madarihat-Hasimara and Rajabhatkhawa-Alipurduar Junction stretches; none in past two years per a forest official; AI thermal-camera detection works at 700-750 m","kind":"report","src":[{"l":"News Arena","u":"https://newsarenaindia.com/states/ai-forest-railways-collaboration-cuts-elephant-deaths-n-bengal/68923"}]},{"id":"01-31","topic":"nature","ctx":"Elephant corridors and human-wildlife conflict relevant to visitors","text":"Crop-raiding seasons: corn mid-May to end July; paddy mid-Sept to Nov; lone elephants raid houses Dec-Jan. Community Quick Response Teams use walkie-talkies; farmers report damage cut by up to 90%","kind":"report","src":[{"l":"Down To Earth","u":"https://www.downtoearth.org.in/agriculture/conflict-in-the-backyard-community-patrols-cut-crop-damage-in-north-bengal-but-south-bengals-farmers-remain-exposed"}]},{"id":"01-32","topic":"nature","ctx":"Elephant corridors and human-wildlife conflict relevant to visitors","text":"Visitor advisory: Gorumara walking on metalled roads allowed but unsafe due to elephants, gaur and rhino","kind":"report","src":[{"l":"Wikipedia: Gorumara","u":"https://en.wikipedia.org/wiki/Gorumara_National_Park"}]},{"id":"03-33","topic":"places","ctx":"Region framing","text":"Dooars: alluvial floodplain about 30 km wide, about 350 km long, Teesta to Dhansiri; Sankosh divides Eastern and Western Dooars. Wikipedia notes the article needs more citations.","kind":"report","src":[{"l":"Wikipedia Dooars","u":"https://en.wikipedia.org/wiki/Dooars"}]},{"id":"03-34","topic":"places","ctx":"Region framing","text":"Main gateways: Bagdogra airport and NJP; stations in region include Malbazar, Hasimara, Alipurduar, Cooch Behar; private car from Bagdogra/NJP recommended.","kind":"operator","src":[{"l":"north-bengal.com Dooars","u":"https://north-bengal.com/dooars.php"}]},{"id":"03-35","topic":"places","ctx":"Region framing","text":"Bagdogra to NJP is about 18 km / about 45 min by taxi; shared taxis NJP to Gorumara/Jaldapara generally not available, prepaid taxis used.","kind":"operator","src":[{"l":"darjeeling-tourism.com","u":"https://darjeeling-tourism.com/darj_000206.htm"}]},{"id":"03-36","topic":"places","ctx":"Region framing","text":"Seasons: Oct-Mar peak; Apr-May warm; Jun-Sep monsoon with forest closures.","kind":"operator","src":[{"l":"north-bengal.com Dooars","u":"https://north-bengal.com/dooars.php"}]},{"id":"03-37","topic":"places","ctx":"Lataguri (Gorumara gateway)","text":"Main town and park entrance on NH717; hub for Gorumara resorts; Ramsai is the other side of the park.","kind":"report","src":[{"l":"Wikipedia Gorumara","u":"https://en.wikipedia.org/wiki/Gorumara_National_Park"}]},{"id":"03-38","topic":"places","ctx":"Lataguri (Gorumara gateway)","text":"About 85 km from NJP by the traditional route, or about 53 km via Gajoldoba.","kind":"operator","src":[{"l":"north-bengal.com Gorumara","u":"https://north-bengal.com/gorumara-national-park-dooars.php"},{"l":"north-bengal search summary","u":"https://northbengaltourism.com/tour-packages/dooars/nbthp0006"}]},{"id":"03-39","topic":"places","ctx":"Lataguri (Gorumara gateway)","text":"Nearest railheads: New Mal Junction (about 18 km) and New Maynaguri; Maynaguri to Lataguri about 20 min.","kind":"report","src":[{"l":"Wikipedia Gorumara","u":"https://en.wikipedia.org/wiki/Gorumara_National_Park"}]},{"id":"03-40","topic":"places","ctx":"Lataguri (Gorumara gateway)","text":"Permits mandatory, booked in advance via Lataguri Forest Office or authorised agents; open-jeep safaris twice daily with licensed guide.","kind":"operator","src":[{"l":"north-bengal.com Gorumara","u":"https://north-bengal.com/gorumara-national-park-dooars.php"}]},{"id":"03-41","topic":"places","ctx":"Lataguri (Gorumara gateway)","text":"Stay: Lataguri main hub, Murti quieter, Chalsa more upscale, Ramsai rural; weak mobile network at Murti and Ramsai.","kind":"operator","src":[{"l":"north-bengal.com Gorumara","u":"https://north-bengal.com/gorumara-national-park-dooars.php"}]},{"id":"03-42","topic":"places","ctx":"Gorumara National Park","text":"Coordinates 26°42′N 88°48′E; area 79.99 km2; Malbazar subdivision, Jalpaiguri; 50 mammal and 194 bird species recorded; leopard only resident big cat; tigers only occasionally seen.","kind":"report","src":[{"l":"Wikipedia","u":"https://en.wikipedia.org/wiki/Gorumara_National_Park"}]},{"id":"03-43","topic":"places","ctx":"Gorumara National Park","text":"Towers/points: Jatraprasad, Rhino Observation Point, Chandrachur, Chukchuki (birding), Medla. Wikipedia states no elephant-back or ranger-led forays and that walking on metalled roads is allowed but risky.","kind":"report","src":[{"l":"Wikipedia","u":"https://en.wikipedia.org/wiki/Gorumara_National_Park"}]},{"id":"03-44","topic":"places","ctx":"Gorumara National Park","text":"Closure: 16 Jun to 15 Sep; best Nov-Mar (Wikipedia); Oct to early April (north-bengal.com).","kind":"operator","src":[{"l":"Wikipedia","u":"https://en.wikipedia.org/wiki/Gorumara_National_Park"},{"l":"north-bengal.com","u":"https://north-bengal.com/gorumara-national-park-dooars.php"}]},{"id":"03-45","topic":"places","ctx":"Gorumara National Park","text":"Fees (secondary, rough): Rs 100 per person entry, 6am-5pm; jeep safari about Rs 1,500-2,500 per jeep (up to 6); elephant safari Rs 1,000-1,500 per person.","kind":"operator","src":[{"l":"TravelTriangle","u":"https://traveltriangle.com/blog/places-to-visit-in-dooars/"}]},{"id":"03-46","topic":"places","ctx":"Chapramari Wildlife Sanctuary","text":"Extension of Gorumara across Murti river; entry Rs 70 per person; 6am-6pm; open 15 Oct-15 Jun (secondary).","kind":"operator","src":[{"l":"TravelTriangle","u":"https://traveltriangle.com/blog/places-to-visit-in-dooars/"}]},{"id":"03-47","topic":"places","ctx":"Chapramari Wildlife Sanctuary","text":"Forms wildlife corridor with Gorumara; known for elephants and gaur.","kind":"operator","src":[{"l":"north-bengal.com Gorumara","u":"https://north-bengal.com/gorumara-national-park-dooars.php"},{"l":"north-bengal.com Dooars","u":"https://north-bengal.com/dooars.php"}]},{"id":"03-48","topic":"places","ctx":"Murti / Rocky Island","text":"Murti: forest bungalow near Chandrachur tower; Murti River flows along park floodplain.","kind":"report","src":[{"l":"Wikipedia Gorumara","u":"https://en.wikipedia.org/wiki/Gorumara_National_Park"}]},{"id":"03-49","topic":"places","ctx":"Murti / Rocky Island","text":"Rocky Island: rocks beside Murti river; camping, bonfire, stargazing; listed best mid-Oct to Dec.","kind":"operator","src":[{"l":"TravelTriangle","u":"https://traveltriangle.com/blog/places-to-visit-in-dooars/"}]},{"id":"03-50","topic":"places","ctx":"Chalsa and Malbazar (tea-belt bases)","text":"Described as tea-garden bases of western Dooars; Malbazar called a melting pot of cultures.","kind":"operator","src":[{"l":"north-bengal.com Dooars","u":"https://north-bengal.com/dooars.php"}]},{"id":"03-51","topic":"places","ctx":"Chalsa and Malbazar (tea-belt bases)","text":"Chalsa about 40 km, Murti 43 km, Lataguri 61 km from Bindu (route-based).","kind":"operator","src":[{"l":"north-bengal.com Bindu","u":"https://www.north-bengal.com/bindu-dooars-dooars.php"}]},{"id":"03-52","topic":"places","ctx":"Chalsa and Malbazar (tea-belt bases)","text":"Wikipedia page for Mal Bazar returned 404 at the URL tried; no coordinates found.","kind":"report","src":[]},{"id":"03-53","topic":"places","ctx":"Nagrakata, Banarhat, Birpara (tea estates)","text":"Listed as tea-garden areas offering plantation walks and settlement visits.","kind":"operator","src":[{"l":"north-bengal.com Dooars","u":"https://north-bengal.com/dooars.php"}]},{"id":"03-54","topic":"places","ctx":"Samsing and Suntalekhola","text":"Samsing: small hill village at about 3,000 ft, Jalpaiguri district, approx 26°59′24″N 88°48′42″E; Neora Valley NP stated about 18 km away (also \"about an hour\"); fog, heavy rainfall; Bhutan hills visible on clear days.","kind":"report","src":[{"l":"Wikipedia Samsing","u":"https://en.wikipedia.org/wiki/Samsing"}]},{"id":"03-55","topic":"places","ctx":"Samsing and Suntalekhola","text":"Suntalekhola: offbeat village at edge of Neora Valley with tea gardens, river, wooden-bridge walk; free; listed Sep-Feb.","kind":"operator","src":[{"l":"TravelTriangle","u":"https://traveltriangle.com/blog/places-to-visit-in-dooars/"}]},{"id":"03-56","topic":"places","ctx":"Neora Valley National Park","text":"Kalimpong district; 27°04′N 88°42′E; 88 km2; established 1986; elevation 183-3,200 m; red panda habitat; much of park inaccessible.","kind":"report","src":[{"l":"Wikipedia","u":"https://en.wikipedia.org/wiki/Neora_Valley_National_Park"}]},{"id":"03-57","topic":"places","ctx":"Neora Valley National Park","text":"Treks reachable from Todey and Tangta (about an hour from Bindu) need Forest Dept permission.","kind":"operator","src":[{"l":"north-bengal.com Bindu","u":"https://www.north-bengal.com/bindu-dooars-dooars.php"}]},{"id":"03-58","topic":"places","ctx":"Neora Valley National Park","text":"The Dooars guide treats Neora as separate from the Dooars circuit.","kind":"operator","src":[{"l":"north-bengal.com Dooars","u":"https://north-bengal.com/dooars.php"}]},{"id":"03-59","topic":"places","ctx":"Gairibas, Jhalong, Paren, Bindu (Jaldhaka river / Bhutan border","text":"Bindu: about 110 km from NJP, 115 km from Bagdogra; Jhalong about 10 km before Bindu; Paren homestay about 6 km from Bindu Dam; Jaldhaka hydel dam site not enterable, viewable from distance; limited accommodation (budget homestays, eco-resorts); Jhalong has a WBFDC tourist lodge.","kind":"operator","src":[{"l":"north-bengal.com Bindu","u":"https://www.north-bengal.com/bindu-dooars-dooars.php"}]},{"id":"03-60","topic":"places","ctx":"Gairibas, Jhalong, Paren, Bindu (Jaldhaka river / Bhutan border","text":"Weekly markets: Jhalong Wednesday market; Bhutanese visitors come to Bindu weekly market. Carry photo ID in border areas. Jhalong to Bindu stated 5 km by one source and 10 km by another.","kind":"operator","src":[{"l":"search summary of north-bengal.com / riddhimart ","u":"https://www.north-bengal.com/jhalong-dooars.php"}]},{"id":"03-61","topic":"places","ctx":"Gairibas, Jhalong, Paren, Bindu (Jaldhaka river / Bhutan border","text":"Jaldhaka hydel project is among the oldest India-Bhutan hydroelectric projects, at the meeting of Dudh Khola, Bindu Khola and Jaldhaka.","kind":"operator","src":[{"l":"north-bengal.com Bindu","u":"https://www.north-bengal.com/bindu-dooars-dooars.php"}]},{"id":"03-62","topic":"places","ctx":"Gairibas, Jhalong, Paren, Bindu (Jaldhaka river / Bhutan border","text":"Paren: about 112 km from Siliguri, railhead Malbazar then Chalsa then jeep; Rachella Pass is best-known trek; Jaldhaka about 10 km. Homestay: Khambuhang Nature Camp.","kind":"report","src":[{"l":"Tale of 2 Backpackers (2017)","u":"https://taleof2backpackers.com/?p=4377"}]},{"id":"03-63","topic":"places","ctx":"Gairibas, Jhalong, Paren, Bindu (Jaldhaka river / Bhutan border","text":"Gairibas: described as a viewpoint over the Jaldhaka winding through forested ridges; no distance found.","kind":"operator","src":[{"l":"search summary","u":"https://www.north-bengal.com/bindu-dooars-dooars.php"}]},{"id":"03-64","topic":"places","ctx":"Gairibas, Jhalong, Paren, Bindu (Jaldhaka river / Bhutan border","text":"Dalgaon: village among tea and ipecac, about 125 km from Siliguri, Bhutan-hill and Jaldhaka views; shared jeeps from Siliguri.","kind":"report","src":[{"l":"Tale of 2 Backpackers","u":"https://taleof2backpackers.com/?p=4377"}]},{"id":"03-65","topic":"places","ctx":"Gairibas, Jhalong, Paren, Bindu (Jaldhaka river / Bhutan border","text":"Rongo: hamlet, about 33 km from New Mal Jn, about 96 km from NJP; monastery and waterfall.","kind":"report","src":[{"l":"Tale of 2 Backpackers","u":"https://taleof2backpackers.com/?p=4377"}]},{"id":"03-66","topic":"places","ctx":"Jaldapara National Park / Madarihat / Hollong","text":"NJP/Bagdogra to Jaldapara about 135 km, 3.5-4 hours (operator).","kind":"operator","src":[{"l":"northbengaltourism.com","u":"https://northbengaltourism.com/tour-packages/dooars/nbthp0006"}]},{"id":"03-67","topic":"places","ctx":"Jaldapara National Park / Madarihat / Hollong","text":"Entry Rs 60 per person; 6am-5pm; Oct-Jun (secondary); jeep safari about Rs 2,000-3,000 per jeep.","kind":"operator","src":[{"l":"TravelTriangle","u":"https://traveltriangle.com/blog/places-to-visit-in-dooars/"}]},{"id":"03-68","topic":"places","ctx":"Jaldapara National Park / Madarihat / Hollong","text":"Madarihat is main access point with hotels, resorts, homestays; Holong Forest Bungalow historically important; elephant rides historically offered at Holong, availability depends on forest rules.","kind":"operator","src":[{"l":"north-bengal.com Dooars","u":"https://north-bengal.com/dooars.php"}]},{"id":"03-69","topic":"places","ctx":"Totopara (Toto tribe)","text":"Offered as add-on to Jaldapara packages with jeep safari.","kind":"operator","src":[{"l":"north-bengal.com Dooars","u":"https://north-bengal.com/dooars.php"}]},{"id":"03-70","topic":"places","ctx":"Chilapata Forest (Hasimara / Kalchini belt)","text":"26°33′02″N 89°22′47″E; about 40 km from Alipurduar, few minutes from Hasimara; elephant corridor Jaldapara-Buxa; ruins of Naranarayan Garh (Nalraja Garh) poorly maintained but archaeologically interesting; WBSFDA eco-resort at Kodalbasti; tonga rides in Mathura tea garden, boating on Bania, angling at Kalchini/Bania/Buri Basra confluence.","kind":"report","src":[{"l":"Wikipedia","u":"https://en.wikipedia.org/wiki/Chilapata_Forest"}]},{"id":"03-71","topic":"places","ctx":"Chilapata Forest (Hasimara / Kalchini belt)","text":"About 145 km from Siliguri; nearest stations New Alipurduar 26 km and Hasimara 16 km (blog); not officially a sanctuary or national park; forests generally closed Jun-Sep. Stays: Chilapata Jungle Camp, Chilapata Inn (Mendabari), 2017 data.","kind":"report","src":[{"l":"Tale of 2 Backpackers","u":"https://taleof2backpackers.com/?p=4377"}]},{"id":"03-72","topic":"places","ctx":"Chilapata Forest (Hasimara / Kalchini belt)","text":"Note the two sources disagree on station distances to Chilapata vs 40 km to Alipurduar (different reference points); verify.","kind":"report","src":[]},{"id":"03-73","topic":"places","ctx":"Hasimara, Kalchini, Hamiltonganj, Rajabhatkhawa (rail/town nodes)","text":"Hasimara is a rail station region node; Rajabhatkhawa is the main Buxa gateway with railway station, Nature Interpretation Centre, forest facilities, and the widest accommodation choice.","kind":"operator","src":[{"l":"east-himalaya.com Buxa","u":"https://www.east-himalaya.com/buxa.php"},{"l":"north-bengal.com Dooars","u":"https://north-bengal.com/dooars.php"}]},{"id":"03-74","topic":"places","ctx":"Hasimara, Kalchini, Hamiltonganj, Rajabhatkhawa (rail/town nodes)","text":"Hamiltonganj, Kalchini: no dedicated sourced data found.","kind":"report","src":[]},{"id":"03-75","topic":"places","ctx":"Buxa Tiger Reserve","text":"Alipurduar district, 26°39′0″N 89°34′48″E, 760 km2; 15th tiger reserve (1983); national park 117.10 km2 notified Dec 1997; 284 bird species; only one resident tiger as of 2005 (stale).","kind":"report","src":[{"l":"Wikipedia","u":"https://en.wikipedia.org/wiki/Buxa_Tiger_Reserve"}]},{"id":"03-76","topic":"places","ctx":"Buxa Tiger Reserve","text":"Closure stated as 16 Jun to 15 Sep, check latest notification; Buxa Bird Festival in January; no Inner Line Permit, but forest areas require permission.","kind":"operator","src":[{"l":"east-himalaya.com Buxa","u":"https://www.east-himalaya.com/buxa.php"}]},{"id":"03-77","topic":"places","ctx":"Buxa Tiger Reserve","text":"Entry Rs 150 per person, 6am-5pm, 15 Oct-15 Jun (secondary, unverified).","kind":"operator","src":[{"l":"TravelTriangle","u":"https://traveltriangle.com/blog/places-to-visit-in-dooars/"}]},{"id":"03-78","topic":"places","ctx":"Santalabari, Buxa Fort, Lepchakha, Rovers Point, Jayanti","text":"Santalabari: road-end start for Buxa Fort trek, about 2 hours on foot; guide required at counter (about Rs 280 in a Team-BHP travelogue; 2019 blog: Rs 250 fort, Rs 300 Lepchakha; stale).","kind":"operator","src":[{"l":"east-himalaya.com","u":"https://www.east-himalaya.com/buxa.php"},{"l":"Team-BHP","u":"https://www.team-bhp.com/forum/assembly-line/215568-dooars-purulia.html"}]},{"id":"03-79","topic":"places","ctx":"Santalabari, Buxa Fort, Lepchakha, Rovers Point, Jayanti","text":"Buxa Fort: ruins, British-era detention camp for political prisoners; distance 2.5-5 km uphill depending on source (conflict).","kind":"operator","src":[{"l":"east-himalaya.com","u":"https://www.east-himalaya.com/buxa.php"},{"l":"Taleof2Backpackers","u":"https://taleof2backpackers.com/trekkers-paradise-buxa-fort/"}]},{"id":"03-80","topic":"places","ctx":"Santalabari, Buxa Fort, Lepchakha, Rovers Point, Jayanti","text":"Rovers Point: about 3-4 km beyond fort at about 4,500 ft; Rs 100 permit in one guide; best Oct, Nov, Feb, Mar.","kind":"report","src":[{"l":"India Guide","u":"https://notify.india-guide.in/destinations/alipurduar/trekking"}]},{"id":"03-81","topic":"places","ctx":"Santalabari, Buxa Fort, Lepchakha, Rovers Point, Jayanti","text":"Lepchakha: Drukpa/Dukpa settlement above fort, basic homestays (Wangmo Homestay, Lepchakha Jungle Camp, 2017 data), about 5.5 km trek from Santalabari.","kind":"operator","src":[{"l":"east-himalaya.com","u":"https://www.east-himalaya.com/buxa.php"},{"l":"Tale of 2 Backpackers","u":"https://taleof2backpackers.com/?p=4377"}]},{"id":"03-82","topic":"places","ctx":"Santalabari, Buxa Fort, Lepchakha, Rovers Point, Jayanti","text":"Jayanti: village on stony Jayanti river bed; Buxa Fort-Jayanti trek about 13 km per forest dept, needs a guide; access affected by monsoon floods; Mahakal cave near river (blog).","kind":"operator","src":[{"l":"east-himalaya.com","u":"https://www.east-himalaya.com/buxa.php"},{"l":"Tripoto","u":"https://www.tripoto.com/jalpaiguri/trips/buxa-fort-jayanti-trek-5e9947b96082e"}]},{"id":"03-83","topic":"places","ctx":"Santalabari, Buxa Fort, Lepchakha, Rovers Point, Jayanti","text":"Raimatang: forest village, about 74 km from Siliguri (UNVERIFIED, looks too short against Alipurduar-based distances), tea gardens, birding, trek to Lepchakha; Raimatang Mountain View Homestay (2017).","kind":"report","src":[{"l":"Tale of 2 Backpackers","u":"https://taleof2backpackers.com/?p=4377"}]},{"id":"03-84","topic":"places","ctx":"Santalabari, Buxa Fort, Lepchakha, Rovers Point, Jayanti","text":"Other lesser-visited forest areas: Khuttimari, Titi, Apalchand, Kathambari (birdwatching).","kind":"operator","src":[{"l":"north-bengal.com Dooars","u":"https://north-bengal.com/dooars.php"}]},{"id":"03-85","topic":"places","ctx":"COOCH BEHAR AND BORDER AREAS","text":"Cooch Behar Palace (Rajbari): 26°19′37″N 89°26′19″E; built 1887 under Maharaja Nripendra Narayan; Italian Renaissance, about 51,309 sq ft, Durbar Hall dome about 124 ft; ASI monument of national importance; now museum.","kind":"report","src":[{"l":"Wikipedia","u":"https://en.wikipedia.org/wiki/Cooch_Behar_Palace"}]},{"id":"03-86","topic":"places","ctx":"COOCH BEHAR AND BORDER AREAS","text":"Timings/fees (conflicting): most say 10am-5pm, closed Friday (one says Tuesday), Indian fee Rs 10-25 (one lists Rs 250), foreigners Rs 250, light-and-sound show reported Fri/Sat 6-8pm.","kind":"operator","src":[{"l":"Holidify, Audiala, Indiano, Travelsetu etc. via ","u":"https://www.holidify.com/places/cooch-behar/rajbari-sightseeing-4432.html"}]},{"id":"03-87","topic":"places","ctx":"BHUTAN-GATEWAY TOWNS","text":"Phuentsholing (Bhutan): 26°51′N 89°23′E, elevation 293 m, Chukha district seat; adjoins Jaigaon; Bhutan Gate; Indian tourists need no visa but need ID and a permit at Phuentsholing; no airport or railway (Hasimara-linked rail was only planned).","kind":"report","src":[{"l":"Wikipedia","u":"https://en.wikipedia.org/wiki/Phuentsholing"}]},{"id":"03-88","topic":"places","ctx":"BHUTAN-GATEWAY TOWNS","text":"Jaigaon: described as larger and busier than Phuentsholing; Jaigaon-Phuentsholing is the main India-Bhutan crossing.","kind":"operator","src":[{"l":"Wikipedia","u":"https://en.wikipedia.org/wiki/Phuentsholing"},{"l":"north-bengal.com Dooars","u":"https://north-bengal.com/dooars.php"}]},{"id":"03-89","topic":"places","ctx":"BHUTAN-GATEWAY TOWNS","text":"Alipurduar is described as a gateway to Bhutan.","kind":"report","src":[{"l":"Wikipedia","u":"https://en.wikipedia.org/wiki/Alipurduar"}]},{"id":"03-90","topic":"places","ctx":"Other","text":"South Khayerbari: rescued-animal centre (about 18 leopards), 10am-4pm, listed for monsoon season; battery-car tours (secondary).","kind":"operator","src":[{"l":"TravelTriangle","u":"https://traveltriangle.com/blog/places-to-visit-in-dooars/"}]},{"id":"03-91","topic":"places","ctx":"Heritage sites","text":"Buxa Fort: British detention camp for political prisoners; ruins only.","kind":"operator","src":[{"l":"east-himalaya.com","u":"https://www.east-himalaya.com/buxa.php"}]},{"id":"03-92","topic":"places","ctx":"Heritage sites","text":"Naranarayan Garh (Nalraja Garh) at Chilapata: ruins.","kind":"report","src":[{"l":"Wikipedia","u":"https://en.wikipedia.org/wiki/Chilapata_Forest"}]},{"id":"03-93","topic":"places","ctx":"Trekking and nature","text":"See Buxa and Paren entries in section 1: Fort-Jayanti about 13 km; Rovers Point best Oct-Nov, Feb-Mar; Neora treks need Forest Dept permission from Todey/Tangta; Jaldhaka riverside, Murti/Rocky Island camping, Chukchuki for birds, Buxa Bird Festival in January.","kind":"report","src":[]},{"id":"03-94","topic":"places","ctx":"Trekking and nature","text":"Chilapata: boating on Bania, angling at confluence.","kind":"report","src":[{"l":"Wikipedia","u":"https://en.wikipedia.org/wiki/Chilapata_Forest"}]},{"id":"05-95","topic":"transport","ctx":"Rail: stations, trains from Kolkata, fares, new projects","text":"Kanchan Kanya Express 13149 (Sealdah to Alipurduar) and 13150 (return): sources conflict on times. 13149 departs Sealdah about 20:30-20:35, arrives Alipurduar Jn about 12:10-12:35 next day; 13150 departs Alipurduar about 15:15-16:00, arrives Sealdah about 08:15-08:20; journey roughly 15.5-16 hours; several sites say daily.","kind":"report","src":[{"l":"indiantrain.in 13149","u":"https://www.indiantrain.in/train-time-table/13149"},{"l":"totaltraininfo 13149","u":"https://www.totaltraininfo.com/train/13149/schedule"}]},{"id":"05-96","topic":"transport","ctx":"Rail: stations, trains from Kolkata, fares, new projects","text":"Vande Bharat Express 22302 (NJP to Howrah) listed departing NJP 15:00, running except Wednesday, about 560 km in 7h30 (aggregator listing, year not stated).","kind":"report","src":[{"l":"railmitra / erail listings via search","u":"https://www.railmitra.com/trains/new-jalpaiguri-to-kolkata"}]},{"id":"05-97","topic":"transport","ctx":"Rail: stations, trains from Kolkata, fares, new projects","text":"Sealdah-NJP Humsafar 13116 (NJP side to Sealdah) takes about 11h40; aggregators count 33-37 trains per week/total between Kolkata and NJP.","kind":"report","src":[{"l":"erail.in Sealdah-NJP","u":"https://erail.in/trains-between-stations/sealdah-SDAH/new-jalpaiguri-NJP"}]},{"id":"05-98","topic":"transport","ctx":"Rail: stations, trains from Kolkata, fares, new projects","text":"17 January 2026: PM Modi flagged off India's first Vande Bharat Sleeper (Howrah-Guwahati/Kamakhya) from Malda; New Cooch Behar-Bamanhat and New Cooch Behar-Boxirhat lines were electrified/dedicated; four Amrit Bharat Express trains flagged off, two from Alipurduar (to Bengaluru SMVT and Mumbai Panvel).","kind":"report","src":[{"l":"The Statesman","u":"https://www.thestatesman.com/india/india-gets-its-first-vande-bharat-sleeper-pm-modi-flags-off-howrah-guwahati-train-from-west-bengals-malda-1503542073.html/amp"},{"l":"The Week, 17 Jan 2026","u":"https://www.theweek.in/news/biz-tech/2026/01/17/west-bengal-pm-modi-flags-off-4-amrit-bharat-express-trains-amid-rs-3250-crore-road-rail-infra-package-announcement.html"}]},{"id":"05-99","topic":"transport","ctx":"Rail: stations, trains from Kolkata, fares, new projects","text":"A New Jalpaiguri-Alipurduar Tourist Special/Express exists as a Wikipedia entry; current running status not confirmed.","kind":"report","src":[{"l":"Wikipedia","u":"https://www.Wikipedia.org/wiki/New_Jalpaiguri%E2%80%93Alipurduar_Tourist_Special"}]},{"id":"05-100","topic":"transport","ctx":"Rail: stations, trains from Kolkata, fares, new projects","text":"Jaldhaka river washed away a culvert on the Altagram-Betgara rail line in an undated flood episode, disrupting North Bengal-Northeast rail links.","kind":"report","src":[{"l":"Outlook Business","u":"https://www.outlookbusiness.com/planet/climate/darjeeling-landslides-bhutan-dam-overflow-flood-alert"}]},{"id":"05-101","topic":"transport","ctx":"Air: Bagdogra, Cooch Behar, Hasimara, Paro","text":"Bagdogra: single terminal, domestic flights from Delhi, Kolkata, Mumbai, Bengaluru; Delhi-Bagdogra about 2h15; Kolkata-Bagdogra quoted 1h10 or about 1h40 (sources differ). Fare snapshots: Delhi-Bagdogra from about Rs 5,000; Bagdogra-Kolkata from Rs 6,849 (dated snapshots). Prepaid taxi counters at airport and NJP.","kind":"report","src":[{"l":"HappyFares Bagdogra guide 2026","u":"https://happyfares.in/blog/?p=2979"},{"l":"Air India","u":"https://www.airindia.com/en/book-flights/bagdogra-to-kolkata-flights"}]},{"id":"05-102","topic":"transport","ctx":"Air: Bagdogra, Cooch Behar, Hasimara, Paro","text":"Cooch Behar airport: Millennium Post reported Kolkata flight to stop from Feb 2026 (operator not renewing contract), later reported weekly flights to continue from Feb 12, and another report says suspended. Aggregators list IndiaOne Air as sole operator (one says 7 weekly as of May 2026). Wikipedia cites 4,297 passengers April 2025-March 2026, down 21.6%.","kind":"report","src":[{"l":"Millennium Post (stop)","u":"https://www.millenniumpost.in/bengal/cooch-beharkolkata-flight-to-stop-from-feb-2026-sparks-row-637989"},{"l":"Millennium Post (weekly)","u":"https://www.millenniumpost.in/bengal/cooch-behar-to-kolkata-flights-to-continue-weekly-from-feb-12-647121"}]},{"id":"05-103","topic":"transport","ctx":"Air: Bagdogra, Cooch Behar, Hasimara, Paro","text":"Bagdogra to Phuentsholing about 165 km, 4-5 hours via Siliguri and Hasimara.","kind":"report","src":[{"l":"littlebhutan.com, page checked 24 Aug 2026","u":"https://littlebhutan.com/travel-guide/entering-bhutan-by-road/"}]},{"id":"05-104","topic":"transport","ctx":"Road and bus","text":"P.C. Mittal Memorial Bus Terminus (Sevoke Road, Siliguri, \"Dooars Bus Stand\") lists routes to Lataguri and Alipurduar.","kind":"report","src":[{"l":"Wikipedia","u":"https://en.wikipedia.org/wiki/P._C._Mittal_Memorial_Bus_Terminus"}]},{"id":"05-105","topic":"transport","ctx":"Road and bus","text":"NBSTC direct buses Jayanti-Alipurduar-Siliguri launched (about 5 am from Jayanti to Siliguri); article date not shown.","kind":"report","src":[{"l":"Millennium Post","u":"https://www.millenniumpost.in/bengal/direct-bus-service-from-jayanti-to-alipurduar-starts-520296"}]},{"id":"05-106","topic":"transport","ctx":"Road and bus","text":"A daily tourist bus from Jaldapara Tourist Lodge/Alipurduar at 7 am stops at Phuentsholing, Jayanti, Rajabhatkhawa, Sikiajhora.","kind":"report","src":[{"l":"Millennium Post","u":"https://www.millenniumpost.in/bengal/new-tourist-bus-service-launched-in-alipurduar-582312"}]},{"id":"05-107","topic":"transport","ctx":"Road and bus","text":"Itinerary distances: Hasimara/NJP to Jaldapara 125.9 km via NH17; Jayanti to Lataguri 132.3 km.","kind":"operator","src":[{"l":"north-bengal.com","u":"https://www.north-bengal.com/buxa-and-jaldapara-tour-dooars-holidays.php"}]},{"id":"05-108","topic":"transport","ctx":"Road and bus","text":"Disruptions: 25 June 2026 massive NH10 landslide near Siliguri cut Sikkim/Kalimpong links; Red Alert for lower Teesta; Teesta, Torsa, Jaldhaka, Raidak, Mahananda rising.","kind":"report","src":[{"l":"ETV Bharat, 25 Jun 2026","u":"https://www.etvbharat.com/en/state/massive-landslide-on-nh-10-in-siliguri-cuts-sikkim-kalimpong-link-enn26062504678"},{"l":"Outlook India","u":"https://www.outlookindia.com/national/west-bengal-floods-death-toll-rises-to-28-as-darjeeling-devastated-by-landslides"}]},{"id":"05-109","topic":"transport","ctx":"Road and bus","text":"Jaigaon border congestion: January 2026 New Year surge caused long queues.","kind":"report","src":[{"l":"Kalimpong Online News, Jan 2026","u":"https://kalimpongonlinenews.blogspot.com/2026/01/tourist-rush-causes-long-queues-at.html"}]},{"id":"05-110","topic":"transport","ctx":"Local transport and safaris","text":"UNI India (Oct 2026): Jaldapara safari booking going online, 48 elephant-ride seats open for advance online booking.","kind":"report","src":[{"l":"UNI India","u":"https://www.uniindia.com/east-india/tourism-wb-jaldapara-durga-puja/214066"}]},{"id":"05-111","topic":"transport","ctx":"Local transport and safaris","text":"Older guides: jeep safari Rs 450 per person or jeep Rs 1,750 for 6; one review Rs 480 for 4 (afternoon jeep), Rs 4,080 for 4 (elephant); park entry Rs 100 Indian / Rs 200 foreign; elephant slots 5:30-6:30 and 6:30-7:30; park open 16 Sep-14 Jun. Bookings via WBTDC Madarihat or WBFDA.","kind":"operator","src":[{"l":"Pickyourtrail","u":"https://pickyourtrail.com/blog/jaldapara-national-park"},{"l":"north-bengal.com Jaldapara","u":"https://north-bengal.com/jaldapara-dooars.php"}]},{"id":"05-112","topic":"transport","ctx":"Bhutan border: Jaigaon-Phuentsholing, permits, SDF","text":"Indians: valid passport (6 months) or original Voter ID; photos; minors without passport need birth certificate; SDF INR 1,200 per day; entry permit from Phuentsholing (+975-05-252383/254639), Gelephu, Samdrup Jongkhar, Samtse offices or Paro airport; carry-cash limits Rs 25,000 (notes up to Rs 500). Page last updated 5 Nov 2026.","kind":"official","src":[{"l":"Embassy of India Thimphu","u":"https://indembthimphu.gov.in/pages/NDA5"}]},{"id":"05-113","topic":"transport","ctx":"Bhutan border: Jaigaon-Phuentsholing, permits, SDF","text":"Pedestrian terminal open 24 hours; vehicle gate about 6am-11pm; Bhutanese immigration 24h; Indian immigration office at Jaigaon on office hours (accounts conflict). Private vehicles Nu 4,500 per car per day; route permits no longer required for tourists within Bhutan (per this operator).","kind":"report","src":[{"l":"littlebhutan.com, checked 24 Aug 2026","u":"https://littlebhutan.com/travel-guide/entering-bhutan-by-road/"}]},{"id":"05-114","topic":"transport","ctx":"Bhutan border: Jaigaon-Phuentsholing, permits, SDF","text":"Border-town day-visit SDF waiver (under 24 hours to Samtse, Phuentsholing, Gelephu, Samdrup Jongkhar), reportedly from 2 June 2026 to Aug 2027, from travel sites only.","kind":"operator","src":[{"l":"Holidify","u":"https://holidify.com/pages/bhutan-visa-for-indians-6749.html"},{"l":"happyfares","u":"https://www.happyfares.in/blog/?p=3417"}]},{"id":"05-115","topic":"transport","ctx":"Bhutan border: Jaigaon-Phuentsholing, permits, SDF","text":"Conflict: stylecraze claims free entry ended July 2026; this contradicts other sources (fee has applied earlier) and is treated as unreliable. Another source states a $15 equivalent; the official Embassy figure is INR 1,200.","kind":"report","src":[{"l":"stylecraze","u":"https://www.stylecraze.com/trending/bhutan-ended-free-entry-for-indians-in-july"}]},{"id":"05-116","topic":"transport","ctx":"Travel from Kolkata: options","text":"See Rail, Air, Road sections above (Kanchan Kanya about 20:30 departure, arriving about 12:10-12:35; Vande Bharat about 7.5h to NJP; flight 1h10-1h40; Bagdogra to Phuentsholing 4-5h).","kind":"report","src":[]},{"id":"06-117","topic":"stay_tea","ctx":"Stays: number, types, registered homestays, prices, seasonality","text":"State-wide: a Bengal tourism official said over 2,000 homestays are registered with the department; Kalimpong 974, Darjeeling about 200; no separate Alipurduar/Jalpaiguri count. Article page header shows Jan 2025 but underlying report date uncertain [NEWS, date uncertain]","kind":"report","src":[{"l":"Telegraph (TTEF mirror)","u":"https://obeta.ttef.in/west-bengal/bengal-tag-cash-for-alipurduar-homestay-accommodations/cid/1877520"}]},{"id":"06-118","topic":"stay_tea","ctx":"Stays: number, types, registered homestays, prices, seasonality","text":"Alipurduar homestay owners began receiving state registration certificates in 2022 [NEWS, 2022]","kind":"report","src":[{"l":"Telegraph via Kalimpong Online News","u":"https://kalimpongonlinenews.blogspot.com/2022/08/bengal-tag-cash-for-alipurduar-homestay.html"}]},{"id":"06-119","topic":"stay_tea","ctx":"Stays: number, types, registered homestays, prices, seasonality","text":"Telegraph feature: \"hundreds of homestays have mushroomed across north Bengal, from the Darjeeling hills to the Dooars\" [NEWS, undated]","kind":"report","src":[{"l":"Telegraph","u":"https://obeta.ttef.in/west-bengal/a-look-at-north-bengals-emerging-tourist-favourite/cid/1729317"}]},{"id":"06-120","topic":"stay_tea","ctx":"Stays: number, types, registered homestays, prices, seasonality","text":"Private hotels are concentrated at Lataguri; state resorts (WBFDC/WBTDCL) at Murti [OPERATOR/guide]","kind":"operator","src":[{"l":"darjeeling-tourism.com","u":"https://www.darjeeling-tourism.com/darj_000209.htm"}]},{"id":"06-121","topic":"stay_tea","ctx":"Stays: number, types, registered homestays, prices, seasonality","text":"Gorumara Wildlife Division (Forest Dept) reopened Dhupjhora Elephant Camp, Kalipur and Mouchuki eco-cottages from 1 Dec 2024 after closure since COVID; double-bed suites at Kalipur and Mouchuki cut from Rs 2,200 to Rs 1,200/night; six Dhupjhora cottages renovated; solar-powered; reference to a fire at Hollong Forest Bungalow, Jaldapara [NEWS, 30 Nov 2024]","kind":"report","src":[{"l":"Millennium Post","u":"https://www.millenniumpost.in/bengal/gorumara-eco-cottages-to-reopen-with-lower-tariffs-from-dec-1-588763"}]},{"id":"06-122","topic":"stay_tea","ctx":"Stays: number, types, registered homestays, prices, seasonality","text":"Hollong Tourist Lodge (Jaldapara) is listed as WBTDCL, bookable via wbtdcl.wbtourismgov.in; WBFDC lodges (e.g., Banani Lodge, Murti) bookable up to 90 days ahead via Salt Lake (Kolkata) office or WBFDC online portal with account [OPERATOR/blog guides, undated]","kind":"official","src":[{"l":"swarnabdutta.com","u":"https://www.swarnabdutta.com/how-to-book-wbfdc-resorts-properties-online"},{"l":"northbengaltourism.com Hollong","u":"https://northbengaltourism.com/hotel-booking/hollong-tourist-lodge/0/"}]},{"id":"06-123","topic":"stay_tea","ctx":"Stays: number, types, registered homestays, prices, seasonality","text":"Season: October to April is best; Dec-Feb peak; June-Sept monsoon, most forest areas closed [OPERATOR, Mar 2026]","kind":"operator","src":[{"l":"Resort Trimurti blog","u":"https://www.resorttrimurti.com/blog/dooars-jungle-safari-price-booking-best-time-complete-travel-guide"}]},{"id":"06-124","topic":"stay_tea","ctx":"Stays: number, types, registered homestays, prices, seasonality","text":"Tea-estate luxury comparators (Darjeeling, not Dooars): Glenburn Rs 28,000-45,000/night double plus taxes; Taj Chia Kutir Rs 20,000-80,000/day; tea tourism packages from Rs 10,000 pp for 2N/3D [NEWS, 28 May 2023]","kind":"report","src":[{"l":"ThePrint","u":"https://www.theprint.in/ground-reports/darjeeling-tea-estates-are-now-luxury-tourism-hotspots-taj-hotels-offering-leaf-picking-spa/1598651"}]},{"id":"06-125","topic":"stay_tea","ctx":"Stays: number, types, registered homestays, prices, seasonality","text":"Telegraph feature example of north Bengal homestay pricing: Kalimpong Rs 1,000 per person per day with meals [NEWS, undated, Kalimpong not Dooars]","kind":"report","src":[{"l":"Telegraph","u":"https://obeta.ttef.in/west-bengal/a-look-at-north-bengals-emerging-tourist-favourite/cid/1729317"}]},{"id":"06-126","topic":"stay_tea","ctx":"Booking channels, commissions, associations, agent models","text":"2018-19 disputes: Mysuru association (400 members) wanted commission cut to 15% pay-at-hotel / 18% prepaid; FHRAI VP said OTAs normally 12-15% but MakeMyTrip/Goibibo charged 20-40%; Gujarat association set 18% cap; FHRAI put MakeMyTrip and Goibibo on notice Dec 2018 [NEWS, 2018-19]","kind":"report","src":[{"l":"Asian Age","u":"https://www.asianage.com/business/companies/200219/hotels-travel-service-providers-at-war.html"},{"l":"YourStory","u":"https://yourstory.com/2018/12/hotels-association-makemytrip-goibibo-notice"}]},{"id":"06-127","topic":"stay_tea","ctx":"Booking channels, commissions, associations, agent models","text":"Booking.com complaints from hoteliers (Spain association, 2024) [NEWS]","kind":"report","src":[{"l":"10minhotel","u":"https://en.10minhotel.com/2024/07/18/hoteliers-accuse-booking-com-of-unfair-business-practices"}]},{"id":"06-128","topic":"stay_tea","ctx":"Booking channels, commissions, associations, agent models","text":"A north Bengal online platform launched travel shows to promote homestays (visibility via digital channels) [NEWS, c.2024-25]","kind":"report","src":[{"l":"Telegraph","u":"https://obeta.ttef.in/west-bengal/north-bengal-based-online-platform-launches-three-new-travel-shows-to-boost-homestays/cid/2022062"}]},{"id":"06-129","topic":"stay_tea","ctx":"Booking channels, commissions, associations, agent models","text":"State homestay portal reported to help tourists [NEWS, c.2022]","kind":"report","src":[{"l":"Telegraph","u":"https://obeta.ttef.in/west-bengal/portal-on-homestays-to-help-tourists/cid/1875173"}]},{"id":"06-130","topic":"stay_tea","ctx":"Tea tourism: estates, status, ownership, regulation, welfare","text":"210 gardens across Alipurduar and Jalpaiguri, only 45 fully/partially operating [OPERATOR/NGO blog, undated]","kind":"report","src":[{"l":"CASA","u":"https://casa-india.org/blog/?p=5523"}]},{"id":"06-131","topic":"stay_tea","ctx":"Tea tourism: estates, status, ownership, regulation, welfare","text":"Jalpaiguri: 92 large estates; Jalpaiguri 20,575 small tea growers, Alipurduar 458, Cooch Behar 3,530 (Tea Board assessment table, undated)","kind":"official","src":[{"l":"Tea Board PDF","u":"https://teaboard.gov.in/pdf/SmallTea_Growers_in_North_Bengal_Bihar.pdf"},{"l":"Outlook","u":"https://www.outlookindia.com/csr/csr-2019-03/tea-board"}]},{"id":"06-132","topic":"stay_tea","ctx":"Tea tourism: estates, status, ownership, regulation, welfare","text":"Closures: 17 gardens shut 2002-07; reports of up to 32 closed since Feb 2015 affecting about 60,000 people [NEWS]","kind":"report","src":[{"l":"Scroll","u":"https://scroll.in/article/940717/photo-feature-struggle-and-hope-in-the-tea-gardens-of-the%20dooars"},{"l":"The Week","u":"https://www.theweek.in/theweek/statescan/dooars-region-starvation-deaths.html"}]},{"id":"06-133","topic":"stay_tea","ctx":"Tea tourism: estates, status, ownership, regulation, welfare","text":"Recent: three gardens (Chamurchi, Redbank, Surendranagar) abruptly closed (date not visible); six gardens closed/abandoned over bonus disputes, about 7,000 jobless before Durga Puja (year not confirmed) [NEWS]","kind":"report","src":[{"l":"Millennium Post","u":"https://www.millenniumpost.in/bengal/closure-of-3-dooars-tea-gardens-leaves-over-2k-workers-in-crisis-627132"},{"l":"Telegraph","u":"https://obeta.ttef.in/west-bengal/cash-woes-in-tea-bonus-rows-dooars-tea-garden-shutdowns-leave-7000-jobless-before-durga-puja/cid/1973623"}]},{"id":"06-134","topic":"stay_tea","ctx":"Tea tourism: estates, status, ownership, regulation, welfare","text":"Examples: Octavius Tea Resorts: Sylee Bungalow (Sylee Tea Estate) and Nya Sylee Bungalow (near Nagrakata); tea walks, tasting; room counts/prices not stated [OPERATOR, 21 Aug 2026]","kind":"operator","src":[{"l":"Octavius blog","u":"https://octaviustea.digitalpress.blog/heritage-tea-estate-in-dooars/"},{"l":"Windhorse","u":"https://www.windhorsetours.com/hotels/zurantee-heritage-bungalow"}]},{"id":"06-135","topic":"stay_tea","ctx":"Tea tourism: estates, status, ownership, regulation, welfare","text":"Green leaf price about Rs 12-13/kg vs cost Rs 18.52 (small growers) [NEWS]","kind":"report","src":[{"l":"Telegraph","u":"https://obeta.ttef.in/west-bengal/intense-monsoonal-downpour-in-sub-himalayan-bengal-poses-problems-for-small-tea-sector/cid/1953876"}]},{"id":"06-136","topic":"stay_tea","ctx":"Forest tourism: lodges, safaris, fees, online booking","text":"14 Oct 2026: online safari booking commenced at Jaldapara up to one month ahead; 912 daily seats over five routes (Salkumar, Madarihat, Lankapara, Chilapata, Kodalbasti); 48 elephant seats [NEWS]","kind":"report","src":[{"l":"UNI","u":"https://www.uniindia.com/east-india/tourism-wb-jaldapara-durga-puja/214066"}]},{"id":"06-137","topic":"stay_tea","ctx":"Forest tourism: lodges, safaris, fees, online booking","text":"Earlier report: online booking reintroduced for elephant safaris only, car safaris offline (undated)","kind":"report","src":[{"l":"News Arena","u":"https://newsarenaindia.com/states/dooars-elephant-safaris-return-ahead-of-durga-puja/56423"}]},{"id":"06-138","topic":"stay_tea","ctx":"Forest tourism: lodges, safaris, fees, online booking","text":"Fees (2026 operator estimate, not official; page internally inconsistent): Gorumara/Chapramari jeep Rs 2,500-4,000; Jaldapara jeep Rs 3,500-4,500; elephant Rs 1,000-1,500 pp; permit Rs 200-400 pp; guide Rs 300-500; slots 6-8, 8:30-10:30, 14:30-16:30, elephant 5:30-6:30; 4-6 per jeep","kind":"operator","src":[{"l":"Resort Trimurti, Mar 2026","u":"https://www.resorttrimurti.com/blog/dooars-jungle-safari-price-booking-best-time-complete-travel-guide"},{"l":"tourtravelworld","u":"https://www.tourtravelworld.com/packages/jalpaiguri_jeep-safari-holidays.htm"}]},{"id":"06-139","topic":"stay_tea","ctx":"Forest tourism: lodges, safaris, fees, online booking","text":"Buxa: villagers of 18 villages agitating over conservation/livelihood; Association for Conservation & Tourism wrote to CM Suvendu Adhikari on 22 Oct 2026 to resume tourism [NEWS, 23 Oct 2026]","kind":"report","src":[{"l":"UNI","u":"https://www.uniindia.com/east-india/tourism-wb-buxa-crisis/223086"},{"l":"UNI 7 Oct 2026","u":"https://www.uniindia.com/east-india/agitation-wb-buxa-protest/205766"}]},{"id":"06-140","topic":"stay_tea","ctx":"Forest tourism: lodges, safaris, fees, online booking","text":"Raimatang homestay owner: lost 90% of business in six years; only 20% of core zone can be opened for tourism; Jayanti residents rely on homestays, safaris, treks [NEWS]","kind":"report","src":[{"l":"Village Square","u":"https://villagesquare.in/north-bengal-tiger-reserve-without-safari/"}]},{"id":"06-141","topic":"stay_tea","ctx":"Forest tourism: lodges, safaris, fees, online booking","text":"Revenue share with communities mentioned by a forest official (2023)","kind":"report","src":[{"l":"Telegraph","u":"https://obeta.ttef.in/west-bengal/vigilantes-get-part-of-buxa-cash/cid/1930968"}]},{"id":"06-142","topic":"stay_tea","ctx":"Operators and package prices","text":"3N/4D Dooars: Rs 6,000-6,200 pp budget; Rs 9,200-9,625 pp mid; Rs 15,599 pp twin sharing with 3-star Lataguri and WBTDC Jaldapara; lowest advertised Rs 5,300; safari/entry/guide often excluded","kind":"operator","src":[{"l":"tourtravelworld","u":"https://www.tourtravelworld.com/packages/green-dooars-jaldapara-lataguri3n4d-tour-241175.html"},{"l":"Musafir","u":"https://in.musafir.com/Holidays/Beautiful_Dooars.aspx"}]},{"id":"06-143","topic":"stay_tea","ctx":"Problems reported","text":"Buxa tourism shutdown/agitation, Oct 2026 (see section 4); Raimatang decline; offline-only car safari booking historically; tea-garden worker dues/closures; 2025 floods","kind":"report","src":[]},{"id":"06-144","topic":"stay_tea","ctx":"Benchmarks","text":"Darjeeling/Kalimpong: state homestay cash aid reported (Kalimpong)","kind":"report","src":[{"l":"Telegraph","u":"https://obeta.ttef.in/west-bengal/mamata-banerjee-government-allots-cash-aid-for-kalimpong-homestays/cid/1834911"}]},{"id":"12-145","topic":"places","ctx":"Totopara","text":"About 22 km from Madarihat via a single-lane motorable road from NH 31 through Hantapara","kind":"operator","src":[{"l":"Wikipedia Totopara, acc. 2026","u":"https://en.wikipedia.org/wiki/Totopara"},{"l":"north-bengal.com Madarihat, acc. 2026","u":"https://north-bengal.com/madarihat-dooars.php"}]},{"id":"12-146","topic":"places","ctx":"Totopara","text":"Official district page lists access: Bagdogra airport; trains to Falakata, Alipurduar Jn or New Alipurduar; roads from Siliguri, Cooch Behar, Falakata, Alipurduar. It does not state permits, accommodation or distances (separate Accommodation page and a Certified Tourist Guide List PDF exist on the site, not read)","kind":"official","src":[{"l":"alipurduar.gov.in, 2023","u":"https://alipurduar.gov.in/?p=28695"}]},{"id":"12-147","topic":"places","ctx":"Totopara","text":"Road reported as rough with shallow river crossings that can flood in monsoon and cut off the village","kind":"operator","src":[{"l":"blog, 2015","u":"https://week-end-tour.blogspot.com/2015/09/totopara-lankapara.html"}]},{"id":"12-148","topic":"places","ctx":"Madarihat / Hasimara","text":"Madarihat: own station on the NJP-Alipurduar line; Alipurduar Jn ~50 km, Siliguri ~125 km (~3 h), Bagdogra ~135 km; entry point to Jaldapara NP; Totopara ~22 km; South Khairbari Nature Park (rescued tigers/leopards) nearby; Phuentsholing ~45 km; WBTDC Madarihat Tourist Lodge near the Jaldapara entrance.","kind":"operator","src":[{"l":"north-bengal.com, acc. 2026","u":"https://north-bengal.com/madarihat-dooars.php"}]},{"id":"12-149","topic":"places","ctx":"Madarihat / Hasimara","text":"Hasimara is 45 km from Alipurduar and 60 km from Cooch Behar; WBFDC Malangi Lodge (Barodabari, Hasimara, Birpara-Madarihat block) is within 8 km of Hasimara station and 37 km of New Alipurduar; Siliguri ~160 km, Bagdogra ~150 km by that lodge's reckoning","kind":"official","src":[{"l":"WBFDC Alipurduar page, acc. 2026","u":"https://wbfdc.net/Alipurduar"}]},{"id":"12-150","topic":"places","ctx":"Madarihat / Hasimara","text":"WBFDC Mendabari Jungle Lodge (inside Jaldapara, Dakshin Barajhar): ~12 km from Hasimara station, ~20 km from Alipurduar Jn","kind":"official","src":[{"l":"WBFDC, acc. 2026","u":"https://wbfdc.net/Alipurduar"}]},{"id":"12-151","topic":"places","ctx":"Madarihat / Hasimara","text":"Another blog states Madarihat is 12 km from Hasimara","kind":"operator","src":[{"l":"web search summary of travel blog, acc. 2026","u":"https://week-end-tour.blogspot.com/2015/09/totopara-lankapara.html"}]},{"id":"12-152","topic":"places","ctx":"Gajoldoba","text":"Village in Rajganj CD block, Jalpaiguri district; 26.7515°N 88.5856°E; Teesta Barrage built 1985 by Jessop & Co for irrigation; reservoir is a bird-watching centre; Baikunthapur forest surrounds it","kind":"report","src":[{"l":"Wikipedia Gajoldoba, acc. 2026","u":"https://en.wikipedia.org/wiki/Gajoldoba"}]},{"id":"12-153","topic":"places","ctx":"Gajoldoba","text":"Common figure ~25 km from Siliguri (~1 h), ~40 km from Jalpaiguri; one guide says 10 km and another ~30 km","kind":"operator","src":[{"l":"Outlook Traveller","u":"https://www.outlooktraveller.com/News/shikara-sails-its-way-to-west-bengal"},{"l":"1001things","u":"https://1001things.org/gajoldoba/"}]},{"id":"12-154","topic":"places","ctx":"Gajoldoba","text":"State government move to develop viewpoints and brand it a bird sanctuary \"Pakhibitan\" (reported 2024)","kind":"report","src":[{"l":"Telegraph/ttef, 2024","u":"https://obeta.ttef.in/west-bengal/gajoldoba-to-get-new-view-points-under-bengal-governments-tourism-boost-for-jalpaiguri/cid/1975882"}]},{"id":"12-155","topic":"places","ctx":"Gajoldoba","text":"Barrage foundation date conflict: 1985 (Wikipedia) vs foundation stone 19 Jan 1987 (a blog snippet)","kind":"report","src":[]},{"id":"12-156","topic":"places","ctx":"Rasikbil (Cooch Behar)","text":"Wetland/lake in Tufanganj subdivision, Cooch Behar; 26°24'50\"N 89°43'30\"E; ~7.5 km from Kamakhyaguri (nearest station); birds incl. cormorants, storks, ibises, spoonbills, lesser whistling duck, teal, pintail; deer park, crocodile rehabilitation centre, aviary, watch tower","kind":"report","src":[{"l":"Wikipedia Rasikbil, acc. 2026","u":"https://en.wikipedia.org/wiki/Rasikbil"}]},{"id":"12-157","topic":"places","ctx":"Rasikbil (Cooch Behar)","text":"175 ha; ~30 min from Tufanganj; best Sept-March; open daily except Thursday ~9 am-5 pm, tickets at counter; no homestays nearby; \"Rasikbill Nature Education and Wilderness Resort\" run by WBFDC","kind":"operator","src":[{"l":"northbengaltourism.com, acc. 2026","u":"https://northbengaltourism.com/rasikbill"}]},{"id":"12-158","topic":"places","ctx":"Rasikbil (Cooch Behar)","text":"Station conflict: Kamakhyaguri ~6 km (same page) vs New Cooch Behar named in FAQ; Wikipedia says 7.5 km from Kamakhyaguri. Distance to Cooch Behar town given as 15, 35 and 45 km in different tourism sites","kind":"operator","src":[{"l":"Explurger","u":"https://www.explurger.com/pd/w1whgqk9dmsi0nu1z"},{"l":"north-bengal.com","u":"https://north-bengal.com/rasikbil-dooars.html"}]},{"id":"12-159","topic":"places","ctx":"Mal Bazar / Chalsa","text":"Malbazar is a subdivision town (Jalpaiguri); ~55 km from Siliguri, ~65 km from Jalpaiguri (dooars.info); Bagdogra ~74 km; Gorumara NP ~16 km (~30 min); two stations: New Mal Junction (NMZ, express/intercity) and Malbazar (MLBZ, locals/DEMU); New Mal Jn to NJP ~35 km per RailYatri","kind":"operator","src":[{"l":"Wikipedia Malbazar","u":"https://en.wikipedia.org/wiki/Malbazar"},{"l":"dooars.info","u":"https://dooars.info/?p=3094"}]},{"id":"12-160","topic":"places","ctx":"Mal Bazar / Chalsa","text":"Chalsa has its own railway station; most long-distance trains do not stop at Chalsa/Nagrakata","kind":"operator","src":[{"l":"north-bengal.com Jhalong, acc. 2026","u":"https://www.north-bengal.com/jhalong-dooars.php"},{"l":"Expedia Chalsa, acc. 2026","u":"https://www.expedia.com.au/Chalsa.dx6130819"}]},{"id":"12-161","topic":"places","ctx":"Hills/foothills: Jhalong, Bindu, Paren, Samsing, Suntalekhola","text":"Jhalong \"within Kalimpong District\"; ~100 km from NJP/Bagdogra (2.5-3 h) via NH17, turn at Khunia More (10 min from Chalsa/Nagrakata), then Chapramari (12 km), Kumani, Naxal Bridge, Jhalong Bazaar; Bindu dam ~10 km north; Jaldhaka Dam (Bindu barrage) completed 1967; WBFDC Jhalong River Camp (cottages); Humro Home community homestays at Paren/Jhalong/Bindu.","kind":"operator","src":[{"l":"north-bengal.com Jhalong, acc. 2026","u":"https://www.north-bengal.com/jhalong-dooars.php"},{"l":"darjeeling-tourism.com","u":"https://darjeeling-tourism.com/darj_000214.htm"}]},{"id":"12-162","topic":"places","ctx":"Hills/foothills: Jhalong, Bindu, Paren, Samsing, Suntalekhola","text":"Samsing: Matiali CD block, Malbazar subdivision, Jalpaiguri district; 26.9901°N 88.8117°E; ~914 m; Samsing Tea Estate on the Murti river (1,200 ha, work suspended 28 Nov 2005, 1,360 workers per Wikipedia — status may have changed); 18 km from Neora Valley NP; Suntalekhola and Rocky Island listed as picnic spots","kind":"operator","src":[{"l":"Wikipedia Samsing, acc. 2026","u":"https://en.wikipedia.org/wiki/Samsing"},{"l":"north-bengal.com Samsing","u":"https://north-bengal.com/samsing-dooars.php"}]},{"id":"12-163","topic":"places","ctx":"Hills/foothills: Jhalong, Bindu, Paren, Samsing, Suntalekhola","text":"Neora Valley NP: Kalimpong subdivision, 88 sq km, up to 3,200 m at Rachela Pass; ~105 km from NJP via Coronation Bridge, NH-31, Odlabari, Damdim, Gorubathan to Lava, then ~10 km; open 16 Sep-15 Jun, closed ~3 months in monsoon; best Oct-Apr; homestays at Lava and Kolakham","kind":"operator","src":[{"l":"northbengaltourism.com, acc. 2026","u":"https://northbengaltourism.com/neora-valley-national-park"}]},{"id":"12-164","topic":"places","ctx":"Tea estates","text":"Estates on the Chalsa-Samsing route include Aibheel, Samsing and Chalouni; route passes Looksan village","kind":"report","src":[{"l":"Octavius Tea blog (promotional), acc. 2026","u":"https://octaviustea.digitalpress.blog/dooars-sightseeing/"}]},{"id":"12-165","topic":"places","ctx":"Tea estates","text":"Octavius Tea Resorts runs stays inside working estates: Nya Sylee heritage bungalow and Sylee Bungalow (Damdim, Jalpaiguri), packages with meals, tea and factory visit","kind":"report","src":[{"l":"Octavius blog","u":"https://octaviustea.digitalpress.blog/heritage-tea-estate-in-dooars/"},{"l":"Fueler listing","u":"https://fueler.io/octaviustearesorts/sylee-bungalow"}]},{"id":"12-166","topic":"places","ctx":"Duar War 1864-65 / Treaty of Sinchula","text":"1841: Britain annexed Assam Duars from Bhutan, paying Rs 10,000 annually; 1862 Bhutanese raids on Sikkim/Cooch Behar; Jan 1863 Ashley Eden mission reached Punakha, repudiated by Bhutan in April; war 1864-65","kind":"report","src":[{"l":"Wikipedia Duar War, acc. 2026","u":"https://en.wikipedia.org/wiki/Duar_War"}]},{"id":"12-167","topic":"places","ctx":"Duar War 1864-65 / Treaty of Sinchula","text":"Viceroy Lord Lawrence declared war Nov 1864 (one source gives 12 Nov 1864)","kind":"report","src":[{"l":"web summary of Wikipedia/gktoday","u":"https://gktoday.in/bhutan-war-1864-65"}]},{"id":"12-168","topic":"places","ctx":"Duar War 1864-65 / Treaty of Sinchula","text":"Treaty of Sinchula signed 11 Nov 1865 (Lt-Col Herbert Bruce for British India); Bhutan ceded the \"Eighteen Doars\" bordering Rungpoor, Cooch Behar, Assam, Ambaree Fallcottah and hill territory on the left bank of the Teesta; annual allowance rising from Rs 25,000 to Rs 50,000 (paid each 10 January); Bhutan lost roughly a fifth of its territory.","kind":"report","src":[{"l":"Wikipedia Duar War","u":"https://en.wikipedia.org/wiki/Duar_War"},{"l":"countrystudies.us/bhutan/9.htm","u":"https://countrystudies.us/bhutan/9.htm"}]},{"id":"12-169","topic":"places","ctx":"Duar War 1864-65 / Treaty of Sinchula","text":"Forts: Buxa captured by central column; Dalimkote by the third column; Dewangiri taken, lost, then retaken by Maj-Gen Henry Tombs","kind":"report","src":[{"l":"Wikipedia Duar War","u":"https://en.wikipedia.org/wiki/Duar_War"}]},{"id":"12-170","topic":"places","ctx":"Buxa Fort","text":"867 m, Buxa Tiger Reserve, Alipurduar district, ~30 km from Alipurduar; 26°45'17.86\"N 89°34'49.04\"E; Bhutanese outpost; formally handed to British 11 Nov 1865 and rebuilt in stone; detention camp 1930-37, special jail 1942-47 and 1949-51 per researcher Subhamay Dutta; Subhas Bose was not held there.","kind":"report","src":[{"l":"Wikipedia Buxa Fort, acc. 2026","u":"https://en.wikipedia.org/wiki/Buxa_Fort"},{"l":"indianpanorama","u":"https://www.indianpanorama.in/experiences/heritage/forts/buxa-fort.php"}]},{"id":"12-171","topic":"places","ctx":"Cooch Behar Rajbari (Victor Jubilee Palace)","text":"Most sources: built 1887 under Maharaja Nripendra Narayan, Italian Renaissance style (also said to be modelled on Buckingham Palace); one source says 1878 (minority, treat as error); now a museum","kind":"report","src":[{"l":"Square Yards blog","u":"https://squareyards.com/blog/cooch-behar-palace-mnm"},{"l":"Wikipedia mirror","u":"https://ipfs.ssi.eecc.de/ipns/en.wikipedia-on-ipfs.org/wiki/Cooch_Behar_Palace"}]},{"id":"12-172","topic":"places","ctx":"Bengal Dooars Railway","text":"Company formed 1891 in the UK, HQ Domohani, merged into Eastern Bengal Railway 1941; 1936 fleet 19 locomotives, 72 coaches, 473 goods wagons","kind":"report","src":[{"l":"Wikipedia","u":"https://en.wikipedia.org/wiki/Bengal_Dooars_Railway"},{"l":"FIBIS wiki","u":"https://wiki.fibis.org/w/Bengal_Dooars_Railway"}]}];